package io.knowledgebrain.learning;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import io.knowledgebrain.contracts.learning.progress.v1.*;
import io.knowledgebrain.contracts.learning.session.v1.*;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP",matches=".+")
class LearningStudyKafkaIntegrationTest {
 Properties options()throws Exception{var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP"));p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/learning-kafka-test/ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/learning-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/learning-kafka-test/user.key")));return p;}
 @Test void bothNewStreamsCarryExactCommittedBytesVersionsImmutablePinsAndTraceHeaders()throws Exception{
  var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var clock=Clock.systemUTC();var ids=new UuidV7(clock);UUID space=ids.next(),actor=ids.next();String trace="f".repeat(32);var roadmaps=new RoadmapStore(ds,clock);var store=new LearningStudyStore(ds,clock,roadmaps);var root=roadmaps.create(space,actor,"Tracking Kafka","",trace);root=roadmaps.graph(space,root.roadmapId(),actor,1,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","Pinned title","")),List.of()),trace);var roadmap=root.roadmapId();var node=root.nodes().getFirst().nodeId();var progress=store.progress(space,roadmap,node,actor,0,"IN_PROGRESS",trace);store.progress(space,roadmap,node,actor,1,"COMPLETED",trace);store.progress(space,roadmap,node,actor,2,"COMPLETED",trace);
  var start=clock.instant().minusSeconds(3600).truncatedTo(java.time.temporal.ChronoUnit.SECONDS);var input=new LearningStudyStore.Input(node,start.toString(),start.plusSeconds(1800).toString(),"Exact raw\nSession note");String key=UUID.randomUUID().toString().replace("-","");var session=store.record(space,roadmap,actor,key,input,trace).session();assertFalse(store.record(space,roadmap,actor,key,input,trace).created());store.changeSession(space,roadmap,session.sessionId(),actor,1,new LearningStudyStore.Input(node,input.startedAt(),input.endedAt(),"Corrected note"),false,trace);store.changeSession(space,roadmap,session.sessionId(),actor,2,null,true,trace);
  var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid IN (?,?)",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),progress.progressId(),session.sessionId()).forEach(r->expected.put(r.getKey(),r.getValue()));assertEquals(5,expected.size());var p=options();p.put("group.id","learning-validation-"+ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer",StringDeserializer.class.getName());p.put("value.deserializer",ByteArrayDeserializer.class.getName());
  try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("learning.progress.v1","learning.study-session.v1"));var found=new HashSet<String>();var progressVersions=new ArrayList<Long>();var sessionVersions=new ArrayList<Long>();long end=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<5&&System.nanoTime()<end)for(var record:c.poll(Duration.ofSeconds(1))){if(!Set.of(progress.progressId().toString(),session.sessionId().toString()).contains(record.key()))continue;String eventId,actorId,spaceId,traceId,type,artifact;long version;
    if(record.topic().equals("learning.progress.v1")){var e=ProgressEventEnvelopeV1.parseFrom(record.value());var v=ProgressChangedPayloadV1.parseFrom(e.getPayload());eventId=e.getEventId();actorId=e.getActorId();spaceId=e.getSpaceId();traceId=e.getTraceId();type=e.getAggregateType();artifact="progress-events";version=v.getVersion();assertEquals("LearningProgress",type);assertEquals("LearningProgressChanged",e.getEventType());assertEquals(progress.progressId().toString(),e.getAggregateId());assertEquals(node.toString(),v.getNodeId());assertEquals(roadmap.toString(),v.getRoadmapId());assertEquals(version==1?"IN_PROGRESS":"COMPLETED",v.getStatus());assertEquals("PRIVATE",v.getVisibility());assertEquals("learning-service",e.getProducer());assertEquals(7,UUID.fromString(v.getRevisionId()).version());if(!found.contains(eventId))progressVersions.add(version);
    }else{var e=StudySessionEventEnvelopeV1.parseFrom(record.value());var v=StudySessionChangedPayloadV1.parseFrom(e.getPayload());eventId=e.getEventId();actorId=e.getActorId();spaceId=e.getSpaceId();traceId=e.getTraceId();type=e.getAggregateType();artifact="study-session-events";version=v.getVersion();assertEquals("StudySession",type);assertEquals(session.sessionId().toString(),e.getAggregateId());assertEquals(node.toString(),v.getNodeId());assertEquals(roadmap.toString(),v.getRoadmapId());assertEquals("Pinned title",v.getNodeTitle());assertEquals(version==1?"Exact raw\nSession note":"Corrected note",v.getNote());assertEquals(1800,v.getDurationSeconds());assertEquals(version==3?"RETIRED":"ACTIVE",v.getState());assertEquals("PRIVATE",v.getVisibility());assertEquals("learning-service",e.getProducer());assertEquals(7,UUID.fromString(v.getRevisionId()).version());if(!found.contains(eventId))sessionVersions.add(version);}
    assertArrayEquals(expected.get(eventId),record.value());assertEquals(actor.toString(),actorId);assertEquals(space.toString(),spaceId);assertEquals(trace,traceId);assertEquals(7,UUID.fromString(eventId).version());for(var h:Map.of("trace_id",trace,"schema_group","learning","schema_artifact",artifact,"schema_version","1").entrySet()){var header=record.headers().lastHeader(h.getKey());assertNotNull(header);assertEquals(h.getValue(),new String(header.value(),StandardCharsets.UTF_8));}found.add(eventId);
   }assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L),progressVersions);assertEquals(List.of(1L,2L,3L),sessionVersions);}
 }
 @Test void validatorCannotPublishProgressWithItsReadOnlyCredential()throws Exception{var p=options();p.put("key.serializer",StringSerializer.class.getName());p.put("value.serializer",ByteArraySerializer.class.getName());p.put("enable.idempotence","false");p.put("delivery.timeout.ms","10000");p.put("request.timeout.ms","3000");p.put("max.block.ms","5000");try(var producer=new org.apache.kafka.clients.producer.KafkaProducer<String,byte[]>(p)){var error=assertThrows(java.util.concurrent.ExecutionException.class,()->producer.send(new org.apache.kafka.clients.producer.ProducerRecord<>("learning.progress.v1","forbidden-validation-write",new byte[]{0})).get(15,java.util.concurrent.TimeUnit.SECONDS));assertInstanceOf(org.apache.kafka.common.errors.TopicAuthorizationException.class,error.getCause());}}
}
